#!/usr/bin/env python3
import argparse
import sys

def deduplicate(lines, ignore_case=False):
    seen = set()
    unique = []
    for line in lines:
        key = line.lower() if ignore_case else line
        if key not in seen:
            seen.add(key)
            unique.append(line)
    return unique

def main():
    parser = argparse.ArgumentParser(
        description="Remove duplicate lines from a file, preserving order."
    )
    parser.add_argument("input_file", help="Path to input file")
    parser.add_argument("output_file", nargs="?", default=None,
                        help="Path to output file (default: stdout)")
    parser.add_argument("-i", "--ignore-case", action="store_true",
                        help="Case-insensitive comparison")
    args = parser.parse_args()

    if not args.input_file:
        parser.error("input file required")

    try:
        with open(args.input_file, "r") as f:
            lines = f.readlines()
    except IOError as e:
        parser.error(f"could not read input file: {e}")

    unique_lines = deduplicate(lines, args.ignore_case)

    if args.output_file:
        try:
            with open(args.output_file, "w") as f:
                f.writelines(unique_lines)
        except IOError as e:
            parser.error(f"could not write output file: {e}")
    else:
        sys.stdout.writelines(unique_lines)

if __name__ == "__main__":
    main()
